\begin{equation}
\mathcal{F}^*
:= \inf_{\substack{u\in W^{1,p} \\ +\text{ constraints}}}
	\int_\Omega f(x,u,\nabla u)\,\dx,
\label{eq:primal-vp}
\end{equation}

where $\Omega\subset\R^n$ is open and bounded, $W^{1,p}$ is the Sobolev space of functions $u:\Omega\to\R^m$ such that all components of $u$ and their weak derivatives are integrable in the Lebesgue space $L^p$ for some $p\ge1$, and $\nabla u:\Omega\to\R^{m\times n}$ is the gradient tensor defined in the weak sense. The integrand function $f$ can be any such that the integral is well defined for all admissible $u$, and, as specified in the next section, the constraints can include pointwise or integral conditions over $\Omega$ or its boundary $\partial\Omega$. In general the infimum $\cF^*$ might not be attained, meaning no global minimizer $u$ exists.


\begin{equation}
\label{eq: D}
\cD\varphi(x,y,z) := \sum_{i=1}^n \frac{\partial\varphi_i}{\partial x_i}
+ \sum_{i=1}^n \sum_{j=1}^m z_{ji}\frac{\partial\varphi_i}{\partial y_j}.
\end{equation}

Consider the integral variational problem~\cref{eq:primal-vp}, where $\Omega$ is a bounded open Lipschitz domain. For simplicity we assume that the domain boundary is specified as a finite union, $\partial\Omega = \cup_{i=1}^s \partial\Omega_i$, where each $\partial\Omega_i$ is a smooth compact manifold.
We assume the integrand function $f$ in~\cref{eq:primal-vp} is continuous and gives a well defined integral over $\Omega$ for all $u\in W^{1,p}$ satisfying the constraints. For instance, in the absence of pointwise constraints that would ensure $u(x)$ and $\nabla u(x)$ are uniformly bounded, we assume that $|f(x,y,z)|$ grows no faster than $|y|^p + |z|^p$ as $|y|,|z|\to\infty$.


For the purpose of illustration throughout this section, we suppose the constraints on $u$ in~\cref{eq:primal-vp} include one integral inequality, one pointwise equality on $\Omega$, and one equality on each boundary component $\partial\Omega_i$ (i.e, one boundary condition):


\begin{align}
	\label{int-both}
	\int_\Omega a(x,u,\nabla u) \,\dx &\ge 0,
	\\
	\label{pw-domain}
	c(x,u,\nabla u)&= 0 \quad x\in\Omega,
	\\
	\label{pw-boundary}
	d_i(x,u)&= 0 \quad x\in\partial\Omega_i,\quad i=1,\ldots,s.
	\end{align}

We assume that the functions $a,c,d_i$ are continuous and that $a(x,u,\nabla u)$ is integrable for all $u\in W^{1,p}$.


The constraint $v=\nabla u$ is imposed using the divergence theorem for vector-valued functions $x \mapsto \vphi(x,u(x))$, where $\varphi: \overline{\Omega}\times\mathbb{R}^m \to \mathbb{R}^n$ is continuously differentiable:
\beq
\label{eq:div-theorem}
\int_\Omega\diver_x\vphi(x,u(x))\,\dx - \sum_{i=1}^s \int_{\partial\Omega_i}\varphi(x,u)\cdot n_i(x) \,\dbound = 0.
\eeq

Here, $n_i(x)$ is the outward unit normal vector on $\partial\Omega_i$. Let $\Phi$ denote the set of $\vphi$ for which the above identity holds and for which the map $x \mapsto \varphi(x,u(x))$ is differentiable via the chain rule for all $u\in W^{1,p}(\Omega,\R^m)$. (See~\cite{Fantuzzi2022} for a more explicit characterization of $\Phi$.) Since $\cD\vphi$ in~\cref{eq: D} is defined in order to satisfy $\diver_x\vphi(x,u(x))=\cD\vphi(x,u,\nabla u)$, the left-hand integrand in~\cref{eq:div-theorem} can be replaced by $\cD\vphi(x,u,\nabla u)$. If $v=\nabla u$ weakly, therefore, identity~\cref{eq:div-theorem} holds for all $\vphi\in\Phi$ with the left-hand integrand replaced by $\cD\vphi(x,u,v)$. The proof of~\cite[Lemma~1]{Korda2018} implies that the converse is also true, so the divergence theorem characterizes the weak gradient $\nabla u$. The next Lemma summarizes these observations.


\begin{align}
\tag{\normalsize\theequation a}
\cL^*&\ge
\sup_{\substack{\eta \in \mathbb{R}_+\\\varphi \in \Phi}}
	\inf_{\substack{u\in W^{1,p}\\v\in L^p\\ \text{(\ref{eq:F-div-dual}c,d)}}}\!\!
	\left\{\!\int\limits_\Omega \![f-\eta a + \mathcal{D}\vphi](x,u,v)\,\dx -\sum_{i=1}^s \int\limits_{\partial\Omega_i}\!\!\varphi(x,u)\cdot n_i(x)\,\dbound \right\}
\label{eq:div-dual}
\\
\tag{\normalsize\theequation b}
&\ge
\sup_{\substack{\eta \in \mathbb{R}_+\\\varphi \in \Phi}}
\left\{\! \int\limits_{\Omega}\!\!\!\! \inf_{\substack{ y\in \R^m \\ z \in \R^{m\times n}\\c(x,y,z)=0}}\!\!\![f-\eta a + \mathcal{D}\vphi](x,y,z)\, \dx+ \sum_{i=1}^s \int\limits_{\partial\Omega_i}\!\! \inf_{\substack{y\in\R^m\\d_i(x,y)=0}}\!\!\!\!-\varphi(x,y)\cdot n_i(x)\dbound\right\}.
\label{eq:relaxed-dual}
\end{align}

Finally, we bound the pointwise infima in~\cref{eq:relaxed-dual} from below by the largest continuous functions $h\in C(\overline{\Omega},\R)$ and $\ell_i\in C(\partial\Omega_i,\R)$ satisfying


\begin{align}
	\label{eq:pw-inequality-bulk}
	f(x,y,z) - \eta\, a(x,y,z) + \mathcal{D}\varphi(x,y,z)  - h(x) &\geq 0 \; \text { on } \Gamma,\\
	-\varphi(x,y)\cdot n_i(x) - \ell_i(x) &\geq 0  \; \text { on } \Lambda_i, \quad i=1,\ldots,s,
	\label{eq:pw-inequality-boundary}
	\end{align}

where $\Gamma$ and $\Lambda_i$ are the sets on which the pointwise constraints are satisfied:


\begin{align}
\label{eq:Gamma-def}
\Gamma &:= \{(x,y,z) \in \Omega \times \mathbb{R}^m \times \mathbb{R}^{m \times n}\colon\; c(x,y,z)= 0\},\\
\Lambda_i &:= \{(x,y) \in \partial\Omega_i \times \mathbb{R}^m \colon \; d_i(x,y)= 0\}. \label{eq:Lambda-def}
\end{align}

\begin{equation}
\label{eq:pdr-2}
\cF^* \geq \cL^* \geq \Lpdr :=
\sup_{\substack{ \eta \in \mathbb{R}_+,\,\varphi \in \Phi,\\ h \in C(\overline{\Omega}),\, \ell_i \in C(\partial\Omega_i)\\ \text{\rm ~(\ref{eq:relaxed-inequalities-all}a,b)} }} \;
\left\{
\int_\Omega h(x) \,\dx
+\sum_{i=1}^s \int_{\partial\Omega_i} \ell_i(x) \,\dbound
\right\},
\end{equation}

We now consider the particular case in which the integral variational problem~\cref{eq:primal-vp} or the integral-constrained optimization problem~\cref{eq:integral-inequality-setup} has polynomial data, meaning that all functions appearing as integrands or in pointwise constraints are polynomial in $(x,u,\nabla u)$, and that the domain $\Omega$ can be specified by polynomials in $x$. Precisely, we assume that $\overline\Omega$ is a basic closed semialgebraic set defined by $s$ polynomial inequalities,
\begin{equation}
\overline\Omega = \{x \in \R^n:\; g_1(x)\ge 0,\,\ldots,\,g_s(x)\ge 0\}.
\label{def-omega}
\end{equation}

We also assume that each $g_i$ vanishes identically on a single boundary component, so
\begin{align}
\partial\Omega_i
&= \{x \in \R^n:\;g_i(x)=0 \text{ and } g_j(x)\geq 0 \text{ for } j\neq i \},
\end{align}

and that $\nabla g_i$ does not vanish anywhere on $\partial\Omega_i$, so the outward unit normal vector is well defined as $n_i(x) = -\nabla g_i/|\nabla g_i|$. Then, the sets $\Gamma$ and $\Lambda_i$ defined in~\cref{eq:Gamma-def,eq:Lambda-def} admit the semialgebraic definitions


\begin{align}
\Gamma &= \{(x,y,z) \in \R^n \times \R^m \times \R^{m\times n}:
c(x,y,z)= 0,\,g_1(x)\ge 0,\ldots,g_s(x)\geq 0\},
\\
\Lambda_i &= \{(x,y) \in \R^n \times \R^m:\,
d_i(x,y) = 0,\,g_i(x)=0,\,
g_j(x)\geq 0 \text{ for } j\neq i
\}.
\end{align}

For any positive integer $\nu$, we can bound $\Lpdr$ from below by restricting the maximization in~\cref{eq:pdr-2} to 
\begin{align}
\vphi &\in \Phi\cap\R^n[x,y]_\nu, &
h &\in \R[x]_\nu, &
\ell_i &= q_i |\nabla g_i| \; \text{ with } \; q_i \in \R[x]_\nu,
\end{align}

where $\R^n[\cdot]_\nu$ is the space of $n$-dimensional vectors of polynomials in the bracketed variables whose degrees are at most $\nu$. More generally, one can choose any finite vector space of polynomials, 
or use rational functions with fixed nonnegative denominators (see \cref{rem:rational} below). The intersection with $\Phi$
excludes polynomials $\vphi(x,y)$ whose degree in $y$ is too large to guarantee integrability of $\cD\vphi(x,u,\nabla u)$ for all $u\in W^{1,p}$. Recalling that $n_i(x) = -\nabla g_i/|\nabla g_i|$ for each $i=1,\ldots,s$, we find
\begin{equation}
\label{eq:vp-finite-dimensional}
\Lpdr\ge
\Lnu :=\!\!\!\!\!\!\!
\sup_{ \substack{\vphi \in \Phi \cap \R^n[x,y]_\nu \\h, q_i \in \R[x]_\nu, \, \eta \in \R_+} }
\!\!\!\!\!\!L(h,q_1,\ldots,q_s)
\;\; \text{s.t.}
\begin{array}[t]{l}
f - \eta a + \mathcal{D}\varphi - h \geq 0  \,\text { on } \Gamma,\\
\varphi\cdot \nabla g_i - q_i|\nabla g_i|^2 \geq 0  \, \text { on } \Lambda_i, 
\end{array}
\end{equation}

where the maximization objective is
\beq
\label{eq:L-objective}
L(h,q_1,\ldots,q_s) : = \int_{\Omega} h(x) \, \dx + \sum_{i=1}^s \int_{\partial\Omega_i} q_i(x)|\nabla g_i(x)| \,\dbound.
\eeq

Problem~\cref{eq:vp-finite-dimensional} is finite-dimensional but still intractable because pointwise polynomial inequalities are NP-hard to verify in general~\cite{Murty1987}. For this reason, we follow a standard approach~\cite{Parrilo2003,Lasserre2001} and strengthen all polynomial nonnegativity constraints into weighted SOS constraints. Letting $\Sigma[\cdot]$ denote the subset of nonnegative polynomials in the bracketed variables that can be written as sums of squares of other polynomials, we consider the sets


\begin{align}
	\mathcal{Q}(\Gamma) &:= \bigg\{\rho c + \sigma_0 + \sum_{i=1}^s g_i \sigma_i:\; \sigma_k \in \Sigma[x,y,z], \,\rho \in \R[x,y,z] \bigg\}, \\
	\mathcal{Q}(\Lambda_i) &:= \bigg\{\rho_1 d_i + \rho_2 g_i  + \sigma_0 + \sum_{j\neq i} g_i \sigma_i:\; \sigma_k \in \Sigma[x,y], \,\rho_j \in \R[x,y] \bigg\}.
	\end{align}

\begin{align}
\label{eq:quad-mods-nu}
	\mathcal{Q}_\nu(\Gamma) &= \mathcal{Q}(\Gamma) \cap \R[x,y,z]_\nu, &
	\mathcal{Q}_\nu(\Lambda_i) &= \mathcal{Q}(\Lambda_i) \cap \R[x,y]_\nu.
\end{align}

Requiring a polynomial to belong to a finite-degree set such as $\cQ_\nu(\Gamma)$ or $\cQ_\nu(\Lambda_i)$ is a \emph{weighted SOS} condition, which can be included as a constraint in an SOS program.


The constraints of~\cref{eq:vp-finite-dimensional}, which enforce polynomial nonnegativity on semialgebraic sets, can be strengthened into weighted SOS constraints to obtain
\begin{equation}
\label{eq:vp-SOS}
\Lnu\ge\Lsos :=\!\!\!\!\!\!\!
\sup_{ \substack{\vphi \in \Phi \cap \R^n[x,y]_\nu\\h, q_i \in \R[x]_\nu, \, \eta \in \R_+} }
\!\!\!\!\!\!L(h,q_1,\ldots,q_s)
\;\; \text{s.t.}
\begin{array}[t]{l}
f - \eta a + \mathcal{D}\varphi - h \in \cQ_\nu(\Gamma),\\
\varphi\cdot \nabla g_i - q_i|\nabla g_i|^2 \in \cQ_\nu(\Lambda_i). 
\end{array}
\end{equation}

