\begin{theorem}
\label{th:sos-variational-problem}
If there exist $r_0,\ldots,r_s \in \R$ such that $r_0^2 - |(x,y,z)|^2 \in \mathcal{Q}(\Gamma)$ and $r_i^2 - |(x,y)|^2 \in \mathcal{Q}(\Lambda_i)$ for $i=1,\ldots,s$, then $\Lsos\nearrow\Lpdr$ as $\nu\to\infty$.
\end{theorem}

