\!\!\!\!\!\!L(h,q_1,\ldots,q_s)
\;\; \text{s.t.}
\begin{array}[t]{l}
f - \eta a + \mathcal{D}\varphi - h \geq 0  \,\text { on } \Gamma,\\
\varphi\cdot \nabla g_i - q_i|\nabla g_i|^2 \geq 0  \, \text { on } \Lambda_i, 
\end{array}
\end{equation}

\begin{align}
	\mathcal{Q}(\Gamma) &:= \bigg\{\rho c + \sigma_0 + \sum_{i=1}^s g_i \sigma_i:\; \sigma_k \in \Sigma[x,y,z], \,\rho \in \R[x,y,z] \bigg\}, \\
	\mathcal{Q}(\Lambda_i) &:= \bigg\{\rho_1 d_i + \rho_2 g_i  + \sigma_0 + \sum_{j\neq i} g_i \sigma_i:\; \sigma_k \in \Sigma[x,y], \,\rho_j \in \R[x,y] \bigg\}.
	\end{align}

\begin{align}
\label{eq:quad-mods-nu}
	\mathcal{Q}_\nu(\Gamma) &= \mathcal{Q}(\Gamma) \cap \R[x,y,z]_\nu, &
	\mathcal{Q}_\nu(\Lambda_i) &= \mathcal{Q}(\Lambda_i) \cap \R[x,y]_\nu.
\end{align}

The constraints of~\cref{eq:vp-finite-dimensional}, which enforce polynomial nonnegativity on semialgebraic sets, can be strengthened into weighted SOS constraints to obtain
\begin{equation}
\label{eq:vp-SOS}
\Lnu\ge\Lsos :=\!\!\!\!\!\!\!
\sup_{ \substack{\vphi \in \Phi \cap \R^n[x,y]_\nu\\h, q_i \in \R[x]_\nu, \, \eta \in \R_+} }
\!\!\!\!\!\!L(h,q_1,\ldots,q_s)
\;\; \text{s.t.}
\begin{array}[t]{l}
f - \eta a + \mathcal{D}\varphi - h \in \cQ_\nu(\Gamma),\\
\varphi\cdot \nabla g_i - q_i|\nabla g_i|^2 \in \cQ_\nu(\Lambda_i). 
\end{array}
\end{equation}

\label{ss:proof-sos-variational}
%The inequalities $\mathbb{L}_{1,{\rm sos}} \leq \mathbb{L}_{2,{\rm sos}} \leq \cdots \leq \mathbb{L}_\infty \leq \mathcal{F}^*$ follow upon combining  \cref{th:variational-porblem-lower-bound} with $\mathbb{L}_{\nu,{\rm sos}} \leq \mathbb{L}_\nu \leq \mathbb{L}_\infty$ and $\mathbb{L}_{\nu,{\rm sos}} \leq \mathbb{L}_{\nu+1,{\rm sos}}$, which holds because truncated quadratic modules satisfy $\mathcal{Q}_\nu \subset \mathcal{Q}_{\nu+1}$. 
%To establish convergence as $\nu \to \infty$ 
It suffices to prove that, for any $\varepsilon>0$, there exists $\nu$ such that 
%\begin{equation}
%\label{eq:epsilon-suboptimality-target-VP}
%\mathbb{L}_{\nu,{\rm sos}} \geq \mathbb{L}_{\infty} - 2\varepsilon.
%\end{equation} 
$\Lsos \geq \Lpdr - 2\varepsilon.$
%
Fix any feasible tuple $(\eta^\varepsilon, \vphi^\varepsilon,h^\varepsilon,\ell_1^\varepsilon,\ldots,\ell_s^\varepsilon)$ for~\cref{eq:relaxed-dual} that satisfies 
%
\begin{equation}
\label{eq:epsilon-suboptimality-nonpoly-VP}
\int_{\Omega} h^\varepsilon(x) \, \dx + \sum_{i=1}^s \int_{\partial\Omega_i} \ell_i^\varepsilon(x) \,\dbound \geq \Lpdr - \varepsilon.
\end{equation}
%
We will use $\vphi^\varepsilon,h^\varepsilon,\ell_1^\varepsilon,\ldots,\ell_s^\varepsilon$ to construct polynomials $\vphi,h,q_1,\ldots,q_s$ such that the tuple $(\eta^\varepsilon, \vphi,h,q_1,\ldots,q_s)$ is feasible for~\cref{eq:vp-SOS} for sufficiently large $\nu$ and achieves an objective value larger than $\Lpdr - 2\varepsilon$. This will imply $\Lsos \geq \Lpdr - 2\varepsilon$.

By assumption, the domain $\Omega$ and the boundary sections $\partial\Omega_i$ are compact and $\abs{\nabla g_i}$ is strictly positive on $\partial\Omega_i$. Moreover, the $(x,y)$ projection of the compact set $\Gamma$, denoted $\Gamma_{xy}$ below, must be a compact subset of $\R^n\times\R^m$. Since polynomials are dense in the space of $t$-times continuously differentiable functions on compact sets for all $t$, we can find polynomial $\vphi$, $h$, $q_1$, $\ldots$, $q_s$ that satisfy
%
\begin{subequations}
	\begin{align}
	\label{eq:poly-approx-1}
	\max_{i=1,\ldots,n} \left\| \vphi_i - \vphi^\varepsilon_i \right\|_{C^1(\Gamma_{xy})} &\leq \beta \varepsilon,\\
	\label{eq:poly-approx-2}
	\left\| h - h^\varepsilon + \alpha_0 \varepsilon \right\|_{C(\Omega)} &\leq \beta \varepsilon,\\
	\label{eq:poly-approx-3}
%	\left\| q_i - \frac{\ell^\varepsilon_i}{\abs{\nabla g_i}} + \frac{\alpha_i\varepsilon}{\abs{\nabla g_i}^2} \right\|_{C(\partial\Omega_i)} &\leq \beta \varepsilon,
	\left\| q_i - \ell^\varepsilon_i \abs{\nabla g_i}^{-1} + \alpha_i\varepsilon \abs{\nabla g_i}^{-2} \right\|_{C(\partial\Omega_i)} &\leq \beta \varepsilon,
	\end{align}
\end{subequations}
%
where $\alpha_0,\ldots,\alpha_s$ and $\beta$ are strictly positive constants to be determined later.

Now choose $\alpha_0 = 2C_0 \beta$ and $\alpha_i = 2C_i \beta$ for all $i=1,\ldots,s$ to obtain
%
\begin{subequations}
	\begin{align}
	f + \mathcal{D}\vphi - \eta^\varepsilon a - h &\geq C_0\beta \varepsilon \quad \text{ on } \Gamma,\\
	\vphi \cdot \nabla g_i - q_i \abs{\nabla g_i}^2 &\geq C_i\beta \varepsilon \quad \text{ on } \Lambda_i, \quad i = 1,\ldots,s.
	\end{align}
\end{subequations}

\begin{align}
\label{eq:epsilon-suboptimality-final-estimate-VP}
\Lsos
&\geq \int_{\Omega} h \, \dx + \sum_{i=1}^s \int_{\partial\Omega_i} q_i \abs{\nabla g_i} \,\dbound
\\\nonumber
&\geq \int_{\Omega} h^\varepsilon\, \dx 
- (\alpha_0+\beta)\vert\Omega\vert \varepsilon
+ \sum_{i=1}^s \int_{\partial\Omega_i} 
	\ell_i^\varepsilon 
	-\beta\varepsilon \abs{\nabla g_i}
	- \alpha_i \varepsilon\abs{\nabla g_i}^{-1}
\,\dbound
\\\nonumber
&\geq \Lpdr - \bigg[ 1+ (2C_0+1)\vert\Omega\vert \beta + \beta \sum_{i=1}^s \int_{\partial\Omega_i} 
\abs{\nabla g_i}
+2C_i \abs{\nabla g_i}^{-1}
\,\dbound
\bigg] \varepsilon.
\end{align}
The second inequality follows from elementary estimates based on~\cref{eq:poly-approx-1,eq:poly-approx-2,eq:poly-approx-3}, while the last one follows from~\cref{eq:epsilon-suboptimality-nonpoly-VP} and our choices for $\alpha_0,\ldots,\alpha_s$. Choosing a sufficiently small positive value for $\beta$ 
%yields~\cref{eq:epsilon-suboptimality-target-VP}, as desired.
yields $\Lsos \geq \Lpdr - 2\varepsilon$, as desired.
